  .filter((l) => l.trim().length > 0)
  .map((l) => {
    const parts = l.split(",");
    return { region: (parts[0] ?? "").trim(), amount: Number(parts[1]) };
  });
const counts = countBy(sales, (s) => s.region);
for (const r of Object.keys(counts).sort()) console.log(`${r}: ${counts[r]}`);
