import * as fs from "fs";
type Cents = number & { readonly __brand: "Cents" };
type Percent = number & { readonly __brand: "Percent" };
function cents(n: number): Cents {
  return n as Cents;
}
function addCents(a: Cents, b: Cents): Cents {
  return cents(a + b);
}
function percent(part: Cents, whole: Cents): Percent {
  return (whole === 0 ? 0 : Math.round((part / whole) * 100)) as Percent;
}
const BUDGETS = {
  food: 5000,
  fun: 2000,
  home: 80000,
} satisfies Record<string, number>;
let total: Cents = cents(0);
for (const line of fs.readFileSync(0, "utf8").trim().split("\n")) {
  const p = line.trim().split(" ");
  total = addCents(total, cents(Math.round(Number(p[1] ?? "0") * 100)));
}
const whole = cents(BUDGETS.food + BUDGETS.fun + BUDGETS.home);
console.log(`Used:     ${percent(total, whole)}%`);

