exercise.solution:
import * as fs from "fs";
const CATEGORIES = ["food", "fun", "home"] as const;
type Category = (typeof CATEGORIES)[number];
interface Entry {
  readonly id: string;
  readonly desc: string;
  readonly cents: number;
  readonly tag: Category;
}
function toCategory(s: string): Category {
  for (const c of CATEGORIES) {
    if (c === s) {
      return c;
    }
  }
  throw new Error(`unknown category: ${s}`);
}
type EntryPatch = Partial<Omit<Entry, "id">>;
type EntrySummary = Pick<Entry, "desc" | "cents">;
type Totals = Record<Category, number>;
function applyPatch(e: Entry, patch: EntryPatch): Entry {
  return { ...e, ...patch };
}
function parsePatch(field: string, value: string): EntryPatch {
  if (field === "desc") {
    return { desc: value };
  }
  if (field === "cents") {
    return { cents: Math.round(Number(value) * 100) };
  }
  if (field === "tag") {
    return { tag: toCategory(value) };
  }
  throw new Error(`unknown field: ${field}`);
}
function summarise(e: Entry): EntrySummary {
  return { desc: e.desc, cents: e.cents };
}
function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}
function totalFor(es: readonly Entry[], tag: Category): number {
  return es.filter((e) => e.tag === tag).reduce((s, e) => s + e.cents, 0);
}
function cheapest(es: readonly Entry[]): EntrySummary {
  const first = es[0];
  if (first === undefined) {
    throw new Error("no entries");
  }
  let best: Entry = first;
  for (const e of es) {
    if (e.cents < best.cents) {
      best = e;
    }
  }
  return summarise(best);
}
let entries: readonly Entry[] = [];
for (const line of fs.readFileSync(0, "utf8").trim().split("\n")) {
  const p = line.trim().split(" ");
  if (p[0] === "patch") {
    const id = p[1] ?? "";
    const patch = parsePatch(p[2] ?? "", p[3] ?? "");
    entries = entries.map((e) => (e.id === id ? applyPatch(e, patch) : e));
  } else {
    entries = [...entries, {
      id: p[0] ?? "",
      desc: p[1] ?? "",
      cents: Math.round(Number(p[2] ?? "0") * 100),
      tag: toCategory(p[3] ?? ""),
    }];
  }
}
const totals: Totals = {
  food: totalFor(entries, "food"),
  fun: totalFor(entries, "fun"),
  home: totalFor(entries, "home"),
};
const byTag = CATEGORIES.filter((c) => totals[c] > 0).map((c) => `${c}=${money(totals[c])}`);
const low = cheapest(entries);
console.log(`Entries:  ${entries.length}`);
console.log(`Total:    ${money(entries.reduce((s, e) => s + e.cents, 0))}`);
console.log(`By tag:   ${byTag.join(", ")}`);
console.log(`Cheapest: ${low.desc} ${money(low.cents)}`);

