import * as fs from "fs";
type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: string };
interface Entry {
  readonly desc: string;
  readonly cents: number;
  readonly tag: string;
}
function asRecord(v: unknown): Record<string, unknown> | undefined {
  if (typeof v !== "object" || v === null) {
    return undefined;
  }
  return v as Record<string, unknown>;
}
function parseEntry(v: unknown, where: string): Result<Entry> {
  const o = asRecord(v);
  if (o === undefined) {
    return { ok: false, error: `${where} must be an object` };
  }
  if (typeof o.desc !== "string") {
    return { ok: false, error: `${where}.desc must be a string` };
  }
  if (typeof o.cents !== "number") {
    return { ok: false, error: `${where}.cents must be a number` };
  }
  if (typeof o.tag !== "string") {
    return { ok: false, error: `${where}.tag must be a string` };
  }
  return { ok: true, value: { desc: o.desc, cents: o.cents, tag: o.tag } };
}
function parseLedger(text: string): Result<readonly Entry[]> {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return { ok: false, error: "not valid JSON" };
  }
  const doc = asRecord(raw);
  if (doc === undefined) {
    return { ok: false, error: "document must be an object" };
  }
  if (!Array.isArray(doc.entries)) {
    return { ok: false, error: "entries must be an array" };
  }
  const list: readonly unknown[] = doc.entries;
  const out: Entry[] = [];
  for (let i = 0; i < list.length; i = i + 1) {
    const r = parseEntry(list[i], `entries[${i}]`);
    if (!r.ok) {
      return r;
    }
    out.push(r.value);
  }
  return { ok: true, value: out };
}
const parsed = parseLedger(fs.readFileSync(0, "utf8"));
if (!parsed.ok) {
  console.log(`Invalid:  ${parsed.error}`);
} else {
  const entries = parsed.value;
  const tags = entries.map((e) => e.tag).filter((t, i, a) => a.indexOf(t) === i).sort();
  const byTag = tags.map((t) => {
    const sum = entries.filter((e) => e.tag === t).reduce((s, e) => s + e.cents, 0);
    return `${t}=$${(sum / 100).toFixed(2)}`;
  });
  console.log(`Entries:  ${entries.length}`);
  console.log(`Total:    $${(entries.reduce((s, e) => s + e.cents, 0) / 100).toFixed(2)}`);
  console.log(`By tag:   ${byTag.join(", ")}`);
}

